132	  // An orphaned-name environment is deliberately excluded — its real ID isn't the one we'd target.
133	  const provisionable = [];
134	
135	  for (const envId of TARGET_ENVIRONMENTS) {
136	    if (existingById.has(envId)) {
137	      log.skip(`Environment '${envId}' already exists`);
