/**
 * STUB replacement for scripts/contentful/setup/_shared.mjs
 * Records every client call instead of hitting the Contentful Management API.
 * Models real CMA semantics that matter here:
 *   - environment.createWithId(target, {name}, source) CLONES the source env's locales
 *     AS THEY STAND AT THAT MOMENT (the whole point of the bug being fixed).
 *   - locale.getMany / locale.create against a non-existent environment THROW 404.
 */
export const log = {
  info:    (m) => console.log(`  [info] ${m}`),
  success: (m) => console.log(`  [ok]   ${m}`),
  skip:    (m) => console.log(`  [skip] ${m}`),
  warn:    (m) => console.warn(`  [warn] ${m}`),
  error:   (m) => console.error(`  [ERR]  ${m}`),
  section: (m) => console.log(`\n== ${m} ==`),
};

export const CALLS = [];
const rec = (method, ...args) => { CALLS.push({ n: CALLS.length + 1, method, args }); };

const SCENARIO = JSON.parse(process.env.STUB_SCENARIO ?? '{}');

// ---- persistent in-memory space state -------------------------------------
// environments: id -> {sys:{id,status}, name}
const environments = new Map();
// locales: envId -> ordered array of codes
const locales = new Map();

function seed() {
  // master always exists
  environments.set('master', { sys: { id: 'master', status: { sys: { id: 'ready' } } }, name: 'master' });
  locales.set('master', [...(SCENARIO.masterLocales ?? [])]);
  for (const e of SCENARIO.environments ?? []) {
    environments.set(e.id, { sys: { id: e.id, status: { sys: { id: 'ready' } } }, name: e.name ?? e.id });
    locales.set(e.id, [...(e.locales ?? [])]);
  }
}
seed();

class NotFound extends Error {
  constructor(envId) { super(`The resource could not be found. environment: ${envId}`); this.status = 404; this.name = 'NotFound'; }
}

function assertEnv(envId, method) {
  if (!environments.has(envId)) {
    rec(`THROW-404 <- ${method}`, envId);
    throw new NotFound(envId);
  }
}

export function checkEnv(required) {
  const missing = required.filter((k) => !process.env[k]);
  if (missing.length) { log.error(`Missing env vars: ${missing.join(', ')}`); process.exit(1); }
}

export function createClient() {
  rec('createClient');
  return {
    environment: {
      getMany: async () => {
        rec('environment.getMany');
        return { items: [...environments.values()] };
      },
      get: async ({ environmentId }) => {
        rec('environment.get', environmentId);
        assertEnv(environmentId, 'environment.get');
        return environments.get(environmentId);
      },
      createWithId: async ({ environmentId }, body, sourceEnvironmentId) => {
        rec('environment.createWithId', environmentId, body, sourceEnvironmentId);
        if ((SCENARIO.failCreate ?? []).includes(environmentId)) {
          const e = new Error(`Simulated create failure for '${environmentId}'`);
          e.status = 500; throw e;
        }
        environments.set(environmentId, { sys: { id: environmentId, status: { sys: { id: 'ready' } } }, name: body.name });
        // CLONE SEMANTICS: snapshot of source locales at this instant.
        const inherited = [...(locales.get(sourceEnvironmentId) ?? [])];
        locales.set(environmentId, inherited);
        rec(`  -> cloned locales from '${sourceEnvironmentId}'`, inherited);
        return environments.get(environmentId);
      },
    },
    locale: {
      getMany: async ({ environmentId }) => {
        rec('locale.getMany', environmentId);
        assertEnv(environmentId, 'locale.getMany');
        return { items: (locales.get(environmentId) ?? []).map((code) => ({ code })) };
      },
      create: async ({ environmentId }, payload) => {
        rec('locale.create', environmentId, payload.code, { default: payload.default, optional: payload.optional, fallbackCode: payload.fallbackCode ?? '(none)' , name: payload.name});
        assertEnv(environmentId, 'locale.create');
        const arr = locales.get(environmentId);
        if (arr.includes(payload.code)) { const e = new Error(`Locale '${payload.code}' already exists`); e.status = 409; throw e; }
        arr.push(payload.code);
        return { code: payload.code };
      },
    },
    apiKey: {
      getMany: async () => { rec('apiKey.getMany'); return { items: (SCENARIO.apiKeys ?? []).map((name) => ({ name })) }; },
      create: async (_s, body) => { rec('apiKey.create', body.name); return body; },
    },
    environmentAlias: {
      getMany: async () => {
        rec('environmentAlias.getMany');
        return { items: (SCENARIO.aliases ?? []).map((a) => ({ sys: { id: a.id }, environment: { sys: { id: a.target } } })) };
      },
      get: async ({ environmentAliasId }) => { rec('environmentAlias.get', environmentAliasId); return { sys: { id: environmentAliasId, version: 1 } }; },
      update: async ({ environmentAliasId }) => { rec('environmentAlias.update', environmentAliasId); return {}; },
      createWithId: async ({ environmentAliasId }) => { rec('environmentAlias.createWithId', environmentAliasId); return {}; },
    },
  };
}

export async function pollForReady(client, environmentId) {
  rec('pollForReady', environmentId);
  return environments.get(environmentId);
}

export async function getExistingEnvironmentIds(client) {
  const { items } = await client.environment.getMany({ query: { limit: 100 } });
  return items.map((e) => e.sys.id);
}

export async function getExistingLocaleCodes(client, environmentId) {
  const { items } = await client.locale.getMany({ environmentId, query: { limit: 100 } });
  return items.map((l) => l.code);
}

