  console.log('\n----- STUB CALL LOG -----');
  for (const c of CALLS) {
    const a = c.args.map((x) => (typeof x === 'object' ? JSON.stringify(x) : String(x))).join(', ');
    console.log(`${String(c.n).padStart(3)}. ${c.method}${a ? `(${a})` : ''}`);
